#!/usr/bin/env node
/**
 * gen-200.js — Genera plantillas de n8n Workflow Templates
 * Formato seguro: cada plantilla en una linea con campos separados por |
 */
const fs=require('fs'),path=require('path');
const base=__dirname;

// Parser: convierte linea pipe-separated a objeto
function T(s){
  const p=s.split('|');
  return {
    cat:p[0], name:p[1], file:p[2], desc:p[3],
    flow:p[4].split(';').map(x=>{const a=x.split('^');return[a[0],a[1]]}),
    creds:p[5]?p[5].split(',').filter(Boolean):[],
    uses:p[6]?p[6].split(','):['Uso general'],
    obs:p[7]?p[7].split(','):['Configura credenciales antes de activar'],
    tags:p[8]?p[8].split(','):['general']
  };
}

