function makeNode(name,typeKey,i){
  const d=NODE_DEFS[typeKey]||NODE_DEFS.http;
  return {parameters:JSON.parse(JSON.stringify(d.params)),id:'n-'+i+'-'+Math.random().toString(36).slice(2,8),name,type:d.type,typeVersion:d.tv,position:[i*260-260,0]};
}
function makeWorkflow(name,flowTypes,labels){
  const nodes=[]; const connections={};
  flowTypes.forEach((t,i)=>{
    const node=makeNode(labels[i]||('Nodo '+(i+1)),t,i);
    if(t==='webhook'||t==='formTrg') node.webhookId='wh-'+i;
    nodes.push(node);
    if(i<flowTypes.length-1) connections[node.name]={main:[[{node:labels[i+1]||('Nodo '+(i+2)),type:'main',index:0}]]};
  });
  return {name,nodes,connections,pinData:{},settings:{executionOrder:'v1'},active:false,tags:[]};
}

// ── Procesar ──
const TEMPLATES=RAW.map(T);
console.log(`Plantillas a generar: ${TEMPLATES.length}`);

let gen=0;
const dataEntries=[];
for(const tpl of TEMPLATES){
  const dir=path.join(base,tpl.cat);
  if(!fs.existsSync(dir)) fs.mkdirSync(dir,{recursive:true});
  const labels=tpl.flow.map(f=>f[0]);
  const types=tpl.flow.map(f=>f[1]);
  const wf=makeWorkflow(tpl.name,types,labels);
  fs.writeFileSync(path.join(dir,tpl.file+'.json'),JSON.stringify(wf,null,2),'utf8');
  gen++;
  dataEntries.push(tpl);
}

// Actualizar data.js
const dataJsPath=path.join(base,'data.js');
let dataJs=fs.readFileSync(dataJsPath,'utf8');
const entriesStr=dataEntries.map(e=>
  `  {cat:"${e.cat}",name:"${e.name}",file:"${e.file}",\n   desc:"${e.desc}",\n   flow:${JSON.stringify(e.flow)},creds:${JSON.stringify(e.creds)},\n   uses:${JSON.stringify(e.uses)},\n   obs:${JSON.stringify(e.obs)},\n   tags:${JSON.stringify(e.tags)}},`
).join('\n');
dataJs=dataJs.replace(/\n\];\s*$/,'\n  // ---- Plantillas generadas (gen-200.js) ----\n'+entriesStr+'\n];');
fs.writeFileSync(dataJsPath,dataJs,'utf8');

console.log(`JSON generados: ${gen}`);
console.log('data.js actualizado');
